import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Array<{text:string,role:string,typography?:any}>} [textContent]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry & material
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Primitive instances container
  const primitiveInstances = [];

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const inst = ctx.primitives[p.name](root, p.params);
      primitiveInstances.push(inst);
    });
  }

  // GSAP timelines for interactions
  const hoverEnterTL = gsap.timeline({ paused: true }).to(mesh.position, {
    y: 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  const hoverLeaveTL = gsap.timeline({ paused: true }).to(mesh.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.in',
  });

  const pressTL = gsap.timeline({ paused: true })
    .to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    })
    .to(mesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power2.out',
    });

  // Event handlers exposed via userData
  root.userData.handlers = {
    hoverEnter: () => hoverEnterTL.restart(),
    hoverLeave: () => hoverLeaveTL.restart(),
    click: () => {
      pressTL.restart();
      ctx.emit('hub-journal.select', {});
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverEnterTL.kill();
    hoverLeaveTL.kill();
    pressTL.kill();
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
    geometry.dispose();
    material.dispose();
  };

  return root;
}
